<?php
 namespace QQWorld\Theme\Model\Theme; class SingleFile { protected $_fileService; public function __construct(\QQWorld\Framework\View\Design\Theme\Customization\FileInterface $fileService) { $this->_fileService = $fileService; } public function update(\QQWorld\Framework\View\Design\ThemeInterface $themeModel, $fileContent) { $customFiles = $themeModel->getCustomization()->getFilesByType($this->_fileService->getType()); $customCss = reset($customFiles); if (empty($fileContent) && $customCss) { $customCss->delete(); return $customCss; } if (!$customCss) { $customCss = $this->_fileService->create(); } $customCss->setData('content', $fileContent); $customCss->setTheme($themeModel); $customCss->save(); return $customCss; } } 